        const hintMarkup=state.conversationHintShown?'<div class="conversation-hint" role="status"><strong>Helpful words</strong><span lang="fi">'+escapeHTML(turn.hintFi||'')+'</span><p>'+escapeHTML(state.help==="bn"?turn.hintBn||'':turn.hintEn||'')+'</p></div>':'';
